{
  "name": "显微图像数据源",
  "name_en": "Microscopy Image Data Source",
  "manufacturer": "",
  "description": "用于在显微镜实验中保存、读取和组织多维图像数据及其元数据的数据源对象，可管理体素尺寸、XYCZT 维度、时间点、通道和 Z 层等信息，常用于实验成像数据的存储与访问。",
  "description_en": "A data source used to store, read, and organize multidimensional microscopy image data and its metadata. It manages information such as voxel size, XYCZT dimensions, timepoints, channels, and z planes, and is commonly used for storing and accessing experimental imaging datasets.",
  "tag_hints": [
    "microscopy image data",
    "multidimensional image storage",
    "XYCZT datasets",
    "voxel size metadata",
    "image file I/O",
    "time-lapse imaging",
    "multi-channel imaging"
  ],
  "actions": [
    {
      "action_name": "auto-mode",
      "description": "获取/设置数据源读写模式",
      "description_en": "Get/set the data source read/write mode."
    },
    {
      "action_name": "auto-setup",
      "description": "执行初始文件设置",
      "description_en": "Perform the initial file setup."
    },
    {
      "action_name": "auto-set_metadata_from_configuration_experiment",
      "description": "根据显微镜实验配置设置元数据",
      "description_en": "Set metadata from the microscope experiment configuration."
    },
    {
      "action_name": "auto-set_metadata",
      "description": "设置数据元数据",
      "description_en": "Set the data metadata."
    },
    {
      "action_name": "auto-write",
      "description": "写入二维图像数据",
      "description_en": "Write 2D image data."
    },
    {
      "action_name": "auto-read",
      "description": "读取数据",
      "description_en": "Read data."
    },
    {
      "action_name": "auto-close",
      "description": "关闭数据源并清理文件句柄",
      "description_en": "Close the data source and clean up file handles."
    },
    {
      "action_name": "auto-nbytes",
      "description": "获取数据源字节大小",
      "description_en": "Get the data source size in bytes."
    },
    {
      "action_name": "auto-data",
      "description": "获取存储数据的数组表示",
      "description_en": "Get the array representation of the stored data."
    },
    {
      "action_name": "auto-voxel_size",
      "description": "获取体素尺寸",
      "description_en": "Get the voxel size."
    },
    {
      "action_name": "auto-shape",
      "description": "获取数据形状（XYCZT）",
      "description_en": "Get the data shape (XYCZT)."
    },
    {
      "action_name": "auto-get_shape_from_metadata",
      "description": "从元数据获取数据形状",
      "description_en": "Get the data shape from metadata."
    },
    {
      "action_name": "auto-get_data",
      "description": "获取指定时间点、位置、通道和 Z 层的数据",
      "description_en": "Get data for the specified timepoint, position, channel, and z plane."
    }
  ]
}

